// Connect opens a pool on DATABASE_URL and checks the connection.
func Connect(ctx context.Context) (*pgxpool.Pool, error) {
	url := os.Getenv("DATABASE_URL")
	if url == "" {
		return nil, errors.New("DATABASE_URL is not set")
	}
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return nil, err
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, err
	}
	return pool, nil
}

// Quote double-quotes an identifier.
func Quote(ident string) string {
	return `"` + strings.ReplaceAll(ident, `"`, `""`) + `"`
}

// Where accumulates equality conditions and positional arguments.
type Where struct {
	conditions []string
	args       []any
}

// NewWhere starts an empty condition list.
func NewWhere() *Where {
	return &Where{}
}

// Eq adds column = value.
func (w *Where) Eq(column string, value any) {
	w.conditions = append(w.conditions, column+" = "+w.Param(value))
}

// In adds column = ANY(values); values is a typed slice pgx can encode as an array.
func (w *Where) In(column string, values any) {
	w.conditions = append(w.conditions, column+" = ANY("+w.Param(values)+")")
}

// Raw adds a condition the caller rendered, with placeholders from Param.
func (w *Where) Raw(condition string) {
	w.conditions = append(w.conditions, condition)
}

// AnyOf adds the conditions joined with OR as one condition.
func (w *Where) AnyOf(conditions []string) {
	w.conditions = append(w.conditions, "("+strings.Join(conditions, " OR ")+")")
}

// Search adds a case-insensitive substring match of text against any of the columns.
func (w *Where) Search(columns []string, text string) {
	pattern := w.Param("%" + EscapeLike(text) + "%")
	parts := make([]string, len(columns))
	for i, column := range columns {
		parts[i] = column + " ILIKE " + pattern
	}
	w.conditions = append(w.conditions, "("+strings.Join(parts, " OR ")+")")
}

// Param appends an argument and returns its placeholder.
func (w *Where) Param(value any) string {
	w.args = append(w.args, value)
	return "$" + strconv.Itoa(len(w.args))
}

// EscapeLike escapes the LIKE wildcards and the escape character itself so text matches literally.
func EscapeLike(text string) string {
	return likeEscaper.Replace(text)
}

var likeEscaper = strings.NewReplacer(`\`, `\\`, "%", `\%`, "_", `\_`)

// SQL renders the WHERE clause, or "" without conditions.
func (w *Where) SQL() string {
	if len(w.conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(w.conditions, " AND ")
}

// Args returns the arguments in placeholder order.
func (w *Where) Args() []any {
	return w.args
}

// Insert renders INSERT ... RETURNING for the values, columns sorted by name.
func Insert(table string, values map[string]any, returning string) (string, []any) {
	columns := sortedKeys(values)
	if len(columns) == 0 {
		return "INSERT INTO " + table + " DEFAULT VALUES RETURNING " + returning, nil
	}
	quoted := make([]string, len(columns))
	placeholders := make([]string, len(columns))
	args := make([]any, len(columns))
	for i, column := range columns {
		quoted[i] = Quote(column)
		placeholders[i] = "$" + strconv.Itoa(i+1)
		args[i] = values[column]
	}
	return "INSERT INTO " + table + " (" + strings.Join(quoted, ", ") + ") VALUES (" + strings.Join(placeholders, ", ") + ") RETURNING " + returning, args
}

// Update renders UPDATE ... RETURNING for the patch, with the key as the last argument.
func Update(table string, values map[string]any, keyColumn string, key any, returning string) (string, []any) {
	columns := sortedKeys(values)
	sets := make([]string, len(columns))
	args := make([]any, 0, len(columns)+1)
	for i, column := range columns {
		args = append(args, values[column])
		sets[i] = Quote(column) + " = $" + strconv.Itoa(len(args))
	}
	args = append(args, key)
	return "UPDATE " + table + " SET " + strings.Join(sets, ", ") + " WHERE " + keyColumn + " = $" + strconv.Itoa(len(args)) + " RETURNING " + returning, args
}

func sortedKeys(values map[string]any) []string {
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

// AppRole is the role requests read and write as: the tenant policies bind it. The migrations create it without
// a login and osl migrate gives it one.
const AppRole = "workspace_app"

// tenantSetting is the setting a statement binds its caller's tenants to, as an array literal; unset or empty,
// no tenant row is visible.
const tenantSetting = "app.team_ids"

const bindSQL = `SELECT set_config($1, $2, true)`

// TenantTable is a table under a tenant policy.
type TenantTable struct {
	Table      string
	Key        string
	PublicRead bool
}

// TenantTables lists every table under a tenant policy.
var TenantTables = []TenantTable{
	{Table: "teams", Key: "id", PublicRead: false},
	{Table: "team_members", Key: "id", PublicRead: false},
	{Table: "projects", Key: "id", PublicRead: false},
	{Table: "tasks", Key: "id", PublicRead: true},
	{Table: "notes", Key: "id", PublicRead: false},
	{Table: "milestones", Key: "id", PublicRead: false},
	{Table: "channels", Key: "id", PublicRead: false},
	{Table: "channel_members", Key: "id", PublicRead: false},
	{Table: "messages", Key: "id", PublicRead: false},
	{Table: "labels", Key: "id", PublicRead: false},
	{Table: "milestone_labels", Key: "id", PublicRead: false},
	{Table: "requests", Key: "id", PublicRead: false},
}

// Scope is what request code reads and writes through under isolation: database. Its methods are the pool's.
// Each statement runs in its own transaction with the tenants of its context bound (Bind), so it reaches the
// rows of those tenants, what a public-read policy shows to everyone, and nothing else; a context nothing was
// bound in reaches no tenant row. System wraps the owner's pool, which the policies do not apply to: jobs act
// through it.
type Scope struct {
	pool  *pgxpool.Pool
	bound bool
}

// ConnectApp opens the pool requests use, on DATABASE_APP_URL, and refuses a role the tenant policies do not bind.
func ConnectApp(ctx context.Context) (*Scope, error) {
	url := os.Getenv("DATABASE_APP_URL")
	if url == "" {
		return nil, errors.New("DATABASE_APP_URL is not set: requests connect as " + AppRole + ", the role the tenant policies bind")
	}
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return nil, err
	}
	tables := make([]string, 0, len(TenantTables))
	for _, t := range TenantTables {
		tables = append(tables, t.Table)
	}
	var unbound int
	err = pool.QueryRow(ctx, `SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = ANY($1) AND NOT row_security_active(c.oid)`, tables).Scan(&unbound)
	if err != nil {
		pool.Close()
		return nil, err
	}
	if unbound > 0 {
		pool.Close()
		return nil, errors.New("DATABASE_APP_URL connects as a role the tenant policies do not bind (a superuser, the tables' owner, or one with BYPASSRLS); connect as " + AppRole)
	}
	return &Scope{pool: pool, bound: true}, nil
}

// System is the owner's pool seen as a Scope: nothing is bound, and nothing needs to be.
func System(pool *pgxpool.Pool) *Scope {
	return &Scope{pool: pool}
}

type binding struct {
	mu      sync.Mutex
	session []string
	created []string
}

type bindingKey struct{}

// WithBinding returns a context whose statements reach no tenant until Bind names the caller's.
func WithBinding(ctx context.Context) context.Context {
	return context.WithValue(ctx, bindingKey{}, &binding{})
}

// Bind names the tenants the context's statements reach: the memberships of its session.
func Bind(ctx context.Context, tenants []string) {
	if b, ok := ctx.Value(bindingKey{}).(*binding); ok {
		b.mu.Lock()
		b.session = tenants
		b.mu.Unlock()
	}
}

// BindTenant adds a tenant the request is about to create, so that its creator can insert it and become its
// first member.
func BindTenant(ctx context.Context, tenant string) {
	if b, ok := ctx.Value(bindingKey{}).(*binding); ok {
		b.mu.Lock()
		b.created = append(b.created, tenant)
		b.mu.Unlock()
	}
}

// boundTenants is the array literal of the context's tenants, or "" when nothing was bound, which shows no tenant row.
func boundTenants(ctx context.Context) string {
	b, ok := ctx.Value(bindingKey{}).(*binding)
	if !ok {
		return ""
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	all := append(append([]string{}, b.session...), b.created...)
	return "{" + strings.Join(all, ",") + "}"
}

// NewID makes a random (version 4) uuid: the key of a tenant the request binds before inserting it.
func NewID() (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16]), nil
}

func (s *Scope) batch(ctx context.Context, sql string, args []any) pgx.BatchResults {
	batch := &pgx.Batch{}
	batch.Queue(bindSQL, tenantSetting, boundTenants(ctx))
	batch.Queue(sql, args...)
	return s.pool.SendBatch(ctx, batch)
}

// Query runs a statement that answers rows.
func (s *Scope) Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error) {
	if !s.bound {
		return s.pool.Query(ctx, sql, args...)
	}
	results := s.batch(ctx, sql, args)
	if _, err := results.Exec(); err != nil {
		_ = results.Close()
		return nil, err
	}
	rows, err := results.Query()
	if err != nil {
		_ = results.Close()
		return nil, err
	}
	return &scopedRows{Rows: rows, results: results}, nil
}

// QueryRow runs a statement that answers one row.
func (s *Scope) QueryRow(ctx context.Context, sql string, args ...any) pgx.Row {
	if !s.bound {
		return s.pool.QueryRow(ctx, sql, args...)
	}
	results := s.batch(ctx, sql, args)
	if _, err := results.Exec(); err != nil {
		_ = results.Close()
		return &scopedRow{err: err}
	}
	return &scopedRow{results: results, row: results.QueryRow()}
}

// Exec runs a statement that answers no rows.
func (s *Scope) Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error) {
	if !s.bound {
		return s.pool.Exec(ctx, sql, args...)
	}
	results := s.batch(ctx, sql, args)
	if _, err := results.Exec(); err != nil {
		_ = results.Close()
		return pgconn.CommandTag{}, err
	}
	tag, err := results.Exec()
	if cerr := results.Close(); err == nil {
		err = cerr
	}
	return tag, err
}

// Begin starts a transaction with the context's tenants bound for all of it.
func (s *Scope) Begin(ctx context.Context) (pgx.Tx, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil || !s.bound {
		return tx, err
	}
	if _, err := tx.Exec(ctx, bindSQL, tenantSetting, boundTenants(ctx)); err != nil {
		_ = tx.Rollback(ctx)
		return nil, err
	}
	return tx, nil
}

// scopedRows are the rows of a bound statement; reading them to the end or closing them ends its transaction.
type scopedRows struct {
	pgx.Rows
	results pgx.BatchResults
	done    bool
}

func (r *scopedRows) Next() bool {
	if r.Rows.Next() {
		return true
	}
	r.finish()
	return false
}

func (r *scopedRows) Close() {
	r.Rows.Close()
	r.finish()
}

func (r *scopedRows) finish() {
	if !r.done {
		r.done = true
		_ = r.results.Close()
	}
}

// scopedRow is the row of a bound statement; scanning it ends its transaction.
type scopedRow struct {
	results pgx.BatchResults
	row     pgx.Row
	err     error
}

func (r *scopedRow) Scan(dest ...any) error {
	if r.err != nil {
		return r.err
	}
	err := r.row.Scan(dest...)
	if cerr := r.results.Close(); err == nil {
		err = cerr
	}
	return err
}

// Exists reports whether a row exists whatever the caller's tenants, asked of a function that sees past the
// policy: it tells another tenant's row from a missing one, and reveals nothing a 403 does not.
func (s *Scope) Exists(ctx context.Context, probe string, id any) (bool, error) {
	var found bool
	err := s.QueryRow(ctx, `SELECT `+Quote(probe)+`($1)`, id).Scan(&found)
	return found, err
}

// UnboundTable is what the app role reads of one tenant table with no tenant bound.
type UnboundTable struct {
	Table string   `json:"table"`
	Count int      `json:"count"`
	IDs   []string `json:"ids"`
}

// Unbound is the test hook's probe: what the app role reads of every tenant table with no tenant bound, which
// is nothing except what a public-read policy shows.
func (s *Scope) Unbound(ctx context.Context) ([]UnboundTable, error) {
	out := make([]UnboundTable, 0, len(TenantTables))
	for _, t := range TenantTables {
		entry := UnboundTable{Table: t.Table, IDs: []string{}}
		if err := s.pool.QueryRow(ctx, `SELECT count(*) FROM `+Quote(t.Table)).Scan(&entry.Count); err != nil {
			return nil, err
		}
		rows, err := s.pool.Query(ctx, `SELECT `+Quote(t.Key)+`::text FROM `+Quote(t.Table)+` ORDER BY 1 LIMIT 1000`)
		if err != nil {
			return nil, err
		}
		for rows.Next() {
			var id string
			if err := rows.Scan(&id); err != nil {
				rows.Close()
				return nil, err
			}
			entry.IDs = append(entry.IDs, id)
		}
		if err := rows.Err(); err != nil {
			return nil, err
		}
		out = append(out, entry)
	}
	return out, nil
}
